#include "sio_uart_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

SInt16 sio_uart_rx_t (Sio sio , Sio_Timeout timeout)
{
  #define sio_uart cast_sio_to_sio_uart (sio)

  SInt16  retval = SIO_TIMEOUT ;

  MbxMsg * rx_data = os_mbx_rcev (sio_uart->rx.q_rcev , timeout) ;

  if (rx_data)
    {
      retval = cast_mbx_msg_to_sio_rx_data (rx_data)->data ;

      os_mbx_send (sio_uart->rx.q_free , rx_data) ;
    }

  return retval ;

  #undef sio_uart
}

